#ifndef ENCODER_SM_H
#define ENCODER_SM_H

#include "ui_types.h"

/* -----------------------------------------------------------------------
 * encoder_sm.h
 * TEAM CODE (owner: Tony - display and user interface) - written by the BJT2 team, not generated by STM32CubeMX.
 * BJT2 Sound Modulating Toy — Rotary Encoder State Machine
 * Author: Tony (Display/UI subsystem)
 *
 * Decodes quadrature signals from the Bourns PEC12R-4117F-S0012
 * rotary encoder (12 PPR) into ui_event_t values, one per detent.
 *
 * Quadrature: the knob has two contacts, A and B, that change a quarter
 * of a cycle apart, so one of them always changes first. Which one
 * changes first gives the direction; counting the changes gives how far.
 * A detent is one click of the knob; PPR = pulses (whole A/B cycles) per
 * revolution.
 *
 * The encoder outputs two signals (A and B) that follow this sequence
 * for one clockwise detent (4 transitions per detent at 12 PPR):
 *
 *   A: 1 0 0 1
 *   B: 1 1 0 0
 *
 * Counter-clockwise is the reverse. The state machine only advances
 * through the sequence on valid transitions — bounce-induced transitions
 * that skip steps or reverse mid-sequence are silently rejected.
 *
 * The firmware no longer calls this decoder: since Tony's display update
 * of 26 Sep 2026, TonyTask lets TIM3 count the A/B edges in hardware
 * (encoder mode, see scan_inputs() in Core/Src/tony_ui.c), so no click is
 * lost while the task is busy drawing. This module is still compiled and
 * host-tested (test_ui.c), and shows the same idea in C.
 *
 * No HAL calls. Pin states are passed in as booleans.
 * ----------------------------------------------------------------------- */

/**
 * encoder_sm_init
 * Initialises the encoder state machine to idle.
 * Must be called once before encoder_sm_update.
 *
 * @param enc  Pointer to encoder_sm_t to initialise. NULL is ignored.
 */
void encoder_sm_init(encoder_sm_t *enc);

/**
 * encoder_sm_update
 * Feed current pin states into the state machine.
 * Returns EVENT_VOLUME_UP, EVENT_VOLUME_DOWN, or EVENT_NONE.
 * A non-NONE event is returned exactly once per completed detent.
 *
 * @param enc    Pointer to the encoder state machine struct.
 * @param pins   Current state of encoder pins A and B.
 * @return       EVENT_VOLUME_UP, EVENT_VOLUME_DOWN, or EVENT_NONE.
 */
ui_event_t encoder_sm_update(encoder_sm_t *enc, encoder_pins_t pins);

#endif /* ENCODER_SM_H */
